#pragma once

// The camera support database (blueprint section 3, "User-visible compatibility states" and
// "Support files and capture modes, not just brand names"; section 8, versioned "camera/profile
// database" with data-only updates; ADR 0018).
//
// The database is the asset "camera-support" (asset_manifest.hpp): one document,
// "camera-support.json", schema "lucent.camera-support" version 3, generated by
// `lucent-qualify --from-report <report> --export-support <folder>` from the qualification report
// (ADR 0016) and committed under assets/camera-support/. It maps mode-key patterns to the
// blueprint's states:
//
//   {
//    "schema": "lucent.camera-support",
//    "schema_version": 3,
//    "qualification": {
//     "generated": "2026-10-08T03:13:58Z",      the qualification run (report "generated")
//     "date": "2026-10-08",                     its UTC date, shown to the photographer
//     "tool": "lucent-qualify 0.1.0 (72cb6d170d50-dirty)",
//     "report": "docs/qualification/qualification-report.json",
//     "basis": {                                what a Verified state holds for
//      "decoder": "LibRaw 0.22.2-Release", "decoder_capabilities": ["..."],
//      "decoded_raw_contract": "1.4", "mode_key": 1, "check_suite": 2, "state_rules": 1,
//      "render_pipeline": 3, "develop_pipeline": 3, "dng_opcode_processing": 1,
//      "geometry_operation": 2, "image_area_placement": 1,
//      "develop_engine": [3, 2, 1, ...], "neutral_look": 1, "export": 1,
//      "lens_database": "lens-database (manifest 97c9...)"},
//     "summary": {"modes": 34, "verified": 14, "compatible_unverified": 11, "limited": 6,
//                 "unsupported": 3}
//    },
//    "limitations": [                           every limitation code the entries use
//     {"code": "xtrans_baseline_demosaic", "summary": "...", "meaning": "..."}],
//    "entries": [                               sorted by match
//     {"match": "mk1|fujifilm|x-t4|raf|...",
//      "qualified_key": "mk1|fujifilm|x-t4|raf|...",
//      "image_area": "decoder_inset_crop 6240x4160", "dng_opcodes": [],
//      "state": "limited", "camera": "Fujifilm X-T4",
//      "mode": "RAF lossless compressed", "family": "fujifilm",
//      "limitations": [{"code": "xtrans_baseline_demosaic", "detail": "..."}],
//      "evidence": "13 of 13 checks strong", "evidence_gaps": [], "fixtures": ["..."]}]
//   }
//
// Version 2 (QUA-02, QUA-08; ADR 0018 amendment of 2026-10-08) added the basis' decoder
// capabilities, develop-engine versions (every engine::kDevelopEngineVersions entry), neutral look
// and export versions, and each entry's "image_area" and "dng_opcodes": the probe facts beside the
// mode key that the qualified file had (derive_mode_variant(), mode_key.hpp). A Verified entry holds
// only for a file with the same facts. Version 1 documents are refused (VersionMismatch): none was
// ever released. Version 3 (W13 closure, ADR 0023) adds the basis' "lens_database": the lens
// database the qualification's develop renders corrected lenses with, as they correct Lucent's
// exports (lens_database_basis()); a version-2 document has none (read as ""), so its Verified states
// do not hold for a build that corrects lenses.
//
// Two keys per entry. `match` is what the application compares: the mode key of the probe it makes
// when it imports a file (stage AfterOpen). `qualified_key` is the key the qualification's evidence
// is attached to: the key of the decoded file (ADR 0016). They are equal except where a probe sees a
// provisional value (the Canon S-RAW white level, final only after unpacking: 15 bits at the probe,
// 14 after decoding); the harness records both (the report's lookup_keys) and
// tests/qualification asserts that every fixture's probe finds the entry of its qualified key.
//
// Mode-key patterns. A pattern is a version-1 mode key (mode_key.hpp) in which any of the ten
// components after "mk1" may be "*" (any value). The exported database uses exact keys only;
// patterns exist for curated entries of later data packs (a known limitation of every mode of a
// model, an Unsupported codec at any size). A Verified entry must be exact: the blueprint's
// Verified means "exact model and relevant capture mode", so no pattern can extend it.
//
// Lookup (rules version 1, lookup()): every entry whose pattern matches the key applies. The
// result's state is the worst of their states (Verified < Compatible, unverified < Limited <
// Unsupported, as when several fixtures share a mode, ADR 0016), its limitations are the union of
// theirs, and its labels and evidence are those of the most specific match (fewest wildcards, then
// the first by pattern text). So a broad pattern can only ever make an exact entry's answer more
// conservative, never better. No match: the mode is not in the database.
//
// What the application makes of an answer (live interpretation first, "a missing mandatory step
// always yields Unsupported") is the application's support rules (lucent/application/
// camera_support.hpp). This header defines the data only.
//
// Strictness: as for manifests, a document is understood completely or refused (Corrupt for
// malformed content, unknown members included; VersionMismatch for a newer schema_version).
// write_camera_support() is canonical (sorted entries and codes, one-space indentation, LF, final
// newline): exporting the same report twice gives the same bytes.
//
// Thread-safety: values; const members may be called concurrently.

#include <cstdint>
#include <filesystem>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include <lucent/assets/asset_store.hpp>
#include <lucent/core/error.hpp>
#include <lucent/core/version.hpp>

namespace lucent::assets {

inline constexpr std::string_view kCameraSupportAssetId = "camera-support";
inline constexpr std::string_view kCameraSupportSchema = "lucent.camera-support";
inline constexpr std::uint32_t kCameraSupportSchemaVersion = 3;
// The oldest schema version this build reads (versions 1 and 2 differ in required members; version 3
// adds the basis' lens database, absent from version 2).
inline constexpr std::uint32_t kOldestCameraSupportSchemaVersion = 2;
inline constexpr std::string_view kCameraSupportFileName = "camera-support.json";

// Stable limitation codes (ADR 0016 decision 4): known optional capabilities a mode lacks. The
// qualification detects them from data; the application derives the engine's own ones from the probe
// as well (lucent/application/camera_support.hpp).
inline constexpr std::string_view kLimitationDefaultCrop = "default_crop_not_applied";
inline constexpr std::string_view kLimitationXTransBaseline = "xtrans_baseline_demosaic";
inline constexpr std::string_view kLimitationDualPixel = "dual_pixel_not_processed";
inline constexpr std::string_view kLimitationEnhancedImage = "dng_enhanced_image_not_offered";
inline constexpr std::string_view kLimitationOptionalOperations = "optional_operations_skipped";
inline constexpr std::string_view kLimitationNonSquarePixels = "non_square_pixels";
inline constexpr std::string_view kLimitationPixelShift = "pixel_shift_not_combined";

// The blueprint's four compatibility states, in order of severity: a larger value is worse, so
// std::max() of two states is the more conservative one. Persisted by spelling (to_string) in the
// database, in the application's catalog records and in reports; values append only.
enum class SupportState : std::uint8_t {
    Verified = 1,              // the exact model and capture mode passed Lucent's qualification
    CompatibleUnverified = 2,  // decodes and interprets; no representative quality evidence
    Limited = 3,               // a known optional feature or profile is unavailable
    Unsupported = 4,           // decoding or a mandatory interpretation step is unavailable
};

// "verified", "compatible_unverified", "limited", "unsupported" ("invalid" out of range).
[[nodiscard]] std::string_view to_string(SupportState state) noexcept;
// The inverse of to_string(); std::nullopt for anything else.
[[nodiscard]] std::optional<SupportState> parse_support_state(std::string_view text) noexcept;
// The more conservative of two states.
[[nodiscard]] constexpr SupportState worse(SupportState a, SupportState b) noexcept {
    return a < b ? b : a;
}

// A version-1 mode-key pattern (see the file comment).
class ModePattern {
public:
    // Corrupt ("assets.camera_support") unless `text` is "mk1" followed by ten '|'-separated
    // components, each "*" or a non-empty value without '*'.
    [[nodiscard]] static Expected<ModePattern> parse(std::string_view text);

    // True when `mode_key` (a canonical mode-key text) has the same version and every component
    // equals the pattern's or the pattern's is "*".
    [[nodiscard]] bool matches(std::string_view mode_key) const noexcept;
    [[nodiscard]] std::size_t wildcards() const noexcept;
    [[nodiscard]] const std::string& text() const noexcept { return text_; }

private:
    std::string text_;
    std::vector<std::string> components_;  // the ten components after "mk1"
};

// The words a limitation code is shown with when the application has no wording of its own for it
// (a code added by a later database): user-facing English.
struct LimitationText {
    std::string code;     // stable code, e.g. "xtrans_baseline_demosaic"
    std::string summary;  // short phrase: "X-Trans demosaicing is baseline quality"
    std::string meaning;  // what the photographer gets: one or two sentences
};

// This build's own words for the codes above (the database exporter writes them into the database;
// the application uses them for limitations it derives without a database); std::nullopt for any
// other code.
[[nodiscard]] std::optional<LimitationText> standard_limitation_text(std::string_view code);

struct EntryLimitation {
    std::string code;
    std::string detail;  // the qualification's developer-facing measurement (may be empty)
};

struct CameraSupportEntry {
    std::string match;          // ModePattern text the application's probe key is compared with
    std::string qualified_key;  // the decoded mode key the evidence is attached to (a pattern for
                                // curated entries; exact for Verified ones)
    // The probe facts beside the key that the qualified file had (ModeVariant, mode_key.hpp): its
    // image area ("decoder_inset_crop 8192x5464", "unknown") and its DNG opcodes ("list3:
    // WarpRectilinear", in processing order). A Verified entry holds only for files with the same
    // facts (the application's support rules); "*" (curated entries) matches any area.
    std::string image_area;
    std::vector<std::string> dng_opcodes;
    SupportState state = SupportState::CompatibleUnverified;
    std::string camera;                        // product name, e.g. "Sony A7 IV (ILCE-7M4)"
    std::string mode;                          // capture mode label, e.g. "ARW lossless compressed, M size"
    std::string family;                        // qualification family, e.g. "sony"
    std::vector<EntryLimitation> limitations;  // sorted by code; non-empty exactly for Limited
                                               // (Unsupported entries may list some too)
    std::string evidence;                      // one line, e.g. "13 of 13 checks strong"
    std::vector<std::string> evidence_gaps;    // why it is not Verified (developer-facing)
    std::vector<std::string> fixtures;         // corpus fixtures the state rests on
};

// What a Verified state was established with. The application downgrades Verified entries to
// Compatible, unverified when its own build differs (basis_differences()): every version of what a
// Verified state certifies (decoding, colour, geometry and export, blueprint section 3).
struct QualificationBasis {
    std::string decoder;                            // "LibRaw 0.22.2-Release"
    std::vector<std::string> decoder_capabilities;  // the decoder build's codecs (sorted), e.g. "zlib"
    std::string decoded_raw_contract;               // "1.4"
    std::uint32_t mode_key = 0;
    std::uint32_t check_suite = 0;
    std::uint32_t state_rules = 0;
    std::uint32_t render_pipeline = 0;
    std::uint32_t develop_pipeline = 0;
    std::uint32_t dng_opcode_processing = 0;
    std::uint32_t geometry_operation = 0;
    std::uint32_t image_area_placement = 0;
    // engine::kDevelopEngineVersions, in its order: the stage graph, sensor normalisation, white
    // balance, the demosaic routes, camera colour, the working space, the guided filter, the proxy
    // downscale, DNG opcode processing, the image-area placement and the lens-profile matching rules
    // (ADR 0023).
    std::vector<std::uint32_t> develop_engine;
    std::uint32_t neutral_look = 0;  // engine::kNeutralLookVersion (the as-shot base look)
    std::uint32_t export_version = 0;  // exporter::kExportVersion (written as "export")
    // The lens database the develop renders corrected lenses with (lens_database_basis(): the
    // bundled asset's pinned manifest, "none" without one; schema 3). Empty in a version-2 document.
    std::string lens_database;

    friend bool operator==(const QualificationBasis&, const QualificationBasis&) = default;
};

struct SupportSummary {
    std::uint32_t modes = 0;
    std::uint32_t verified = 0;
    std::uint32_t compatible_unverified = 0;
    std::uint32_t limited = 0;
    std::uint32_t unsupported = 0;

    friend bool operator==(const SupportSummary&, const SupportSummary&) = default;
};

// The answer of a lookup (see the file comment).
struct CameraSupportMatch {
    const CameraSupportEntry* entry = nullptr;                // the most specific matching entry
    SupportState state = SupportState::CompatibleUnverified;  // worst state of every match
    std::vector<std::string> limitations;                     // union of their codes, sorted
    std::size_t matches = 0;                                  // entries that matched
};

struct CameraSupportDatabase {
    std::string generated;  // UTC time of the qualification run, "YYYY-MM-DDTHH:MM:SSZ"
    std::string date;       // its date, "YYYY-MM-DD"
    std::string tool;       // the qualification tool and build
    std::string report;     // repository path of the report it was exported from
    QualificationBasis basis;
    SupportSummary summary;                   // must equal the entries' counts (checked by the parser)
    std::vector<LimitationText> limitations;  // sorted by code
    std::vector<CameraSupportEntry> entries;  // sorted by match

    // The database's answer for a mode key (canonical text); std::nullopt when no entry matches.
    [[nodiscard]] std::optional<CameraSupportMatch> lookup(std::string_view mode_key) const;
    // The text of limitation `code`, or nullptr.
    [[nodiscard]] const LimitationText* limitation(std::string_view code) const noexcept;
    // Counts of `entries` by state.
    [[nodiscard]] SupportSummary count() const noexcept;
};

// Parses and validates a database document (see the file comment). Besides the structure, checks:
// patterns parse and are unique; Verified entries are exact (match, qualified_key and image_area);
// Limited entries list a limitation and Verified or Compatible, unverified entries list none; every
// code an entry uses has a text; the summary equals the entries' counts; a qualified_key parses as a
// pattern. Errors (where "assets.camera_support"): VersionMismatch for another schema or a
// schema_version this build does not read (older than kOldestCameraSupportSchemaVersion or newer
// than kCameraSupportSchemaVersion); Corrupt otherwise.
[[nodiscard]] Expected<CameraSupportDatabase> parse_camera_support(std::string_view json);

// The canonical document (see the file comment). Entries are written sorted by match,
// limitations by code, and the summary is recomputed. InvalidArgument when the database would not
// parse back (the rules of parse_camera_support()). Written as camera_support_schema_version().
[[nodiscard]] Expected<std::string> write_camera_support(const CameraSupportDatabase& database);

// The schema version a database's document is written as: kCameraSupportSchemaVersion (3) when its
// basis names the lens database the qualification corrected lenses with, 2 when it names none (the
// export of a qualification report made before lens corrections, which has no lens database to
// record: as before W13, and such a basis never holds for a build that corrects lenses).
[[nodiscard]] std::uint32_t camera_support_schema_version(const CameraSupportDatabase& database) noexcept;

// The qualification basis of the running build: its decoder (LibRaw's version and capabilities),
// decoded-RAW contract, mode-key version, the pipeline and engine versions, the neutral look and
// the export version. check_suite and state_rules are 0: they describe how evidence was weighed,
// not what this build renders, and are not compared.
[[nodiscard]] QualificationBasis running_basis();

// How `qualified` differs from `running` in what a verification depends on (every member but
// check_suite and state_rules), one developer-facing line per difference ("decoder: qualified with
// LibRaw 0.22.2-Release, this build uses LibRaw 0.23.0-Release"). Empty when Verified entries hold
// for the running build.
[[nodiscard]] std::vector<std::string> basis_differences(const QualificationBasis& qualified,
                                                         const QualificationBasis& running);

// The camera support database a session uses: the activated asset and its content.
struct CameraSupport {
    std::string asset_id;  // kCameraSupportAssetId
    core::SemanticVersion version;
    AssetOrigin origin = AssetOrigin::Bundled;
    std::filesystem::path folder;
    core::Digest256 manifest_sha256{};
    CameraSupportDatabase database;
    // basis_differences(database.basis, running basis); empty when its Verified entries hold.
    std::vector<std::string> basis_differences;

    // "1.0.0" etc.
    [[nodiscard]] std::string version_text() const { return version.to_string(); }
    [[nodiscard]] bool verified_entries_hold() const noexcept { return basis_differences.empty(); }
};

// The outcome of loading the database at start-up.
struct CameraSupportLoad {
    std::shared_ptr<const CameraSupport> active;  // null when none could be activated
    std::vector<AssetCandidate> candidates;       // every location looked at, in lookup order
    std::optional<Error> problem;                 // why `active` is null
};

// Finds and verifies the asset (find_asset with `request`), checks that its content is
// "lucent.camera-support" in a version this build reads, parses it and compares its basis with
// running_basis(). A database that fails any step is not activated: `problem` says why (VersionMismatch
// for a content schema this build cannot read; parse_camera_support()'s errors; find_asset()'s).
[[nodiscard]] CameraSupportLoad load_camera_support(const AssetLocations& locations,
                                                    const AssetRequest& request);

// The camera support database from verified bytes (tests and tools): the content check, the parse
// and the basis comparison of load_camera_support().
[[nodiscard]] Expected<std::shared_ptr<const CameraSupport>> activate_camera_support(
    const VerifiedAsset& asset);

}  // namespace lucent::assets
